"""Create requested T5.8 report from immutable experiment outputs."""
import json,sys
from pathlib import Path
base=Path(__file__).parent
selection=json.loads((base/'selection.json').read_text())
metrics=json.loads((base/'accuracy/metrics.json').read_text())
supp=json.loads((base/'supplementary-metrics.json').read_text())['runs']
final=Path(sys.argv[1]) if len(sys.argv)>1 else base
final.mkdir(parents=True,exist_ok=True)
lines=['# T5.8 — Escalation selection and held-out result','','## Procedure','','Dev runs A then B were executed strictly sequentially, each on the 20 canonical dev CV×JD pairs. Common flags: `--model ag/gemini-3.8-flash-low --prompt-version screening-v2 --context-mode retrieved --retrieval-mode lexical --retrieval-k 5 --concurrency 1 --hedge-after-s 20`; escalation band fixed at `[0.7, 0.9)`. A requests `ag/gemini-3.8-flash-high`; B requests `ag/gemini-4-argon-medium`. No code, canonical labels, or environment files were changed; no commit was made.','','The existing no-escalation dev reference used the same model/prompt/retrieval settings but no hedging. This historical-reference comparison combines escalation with the hedge setting and gateway timing changes; it cannot isolate the escalation effect. Reference: `20261122T083536Z-v2-lexical-gemini-3-8-flash-low-c1`; its earlier offline evaluation is `accuracy-bakeoff-20261122T120520Z`. All three were freshly evaluated offline against dev final labels.','','The approved held-out staging YAML was verified byte-identical to canonical before calls: SHA-256 `ce42cfbff2bd031b7d984d272fd3680a483855290917f47e5271edfa20e97a6f`. Provenance hashes and final verification are in the dev evaluation directory.','','## Intervals and definitions','','Accuracy metrics use unmodified `app.experiments.evaluate` outputs: nominal six-class exact κ; collapsed κ merges strong/adequate/partial into evidence, retains absent, and merges unknown/needs_review; evidence F1 detects binary evidence, not quote overlap; fit accuracy applies guideline rule 5. Accuracy CIs are 95% percentile intervals from 2,000 pair-cluster bootstrap draws with NumPy seed 20261122. Supplemental absent recall and operational intervals use the same seed/draw count; absent draws with zero support are omitted. Success uses a Wilson 95% interval. Count intervals resample totals of 20 pairs. Latency is runner pair latency, including preparation, provider retries, hedging, and both escalation passes, excluding queue/persistence. Percentiles use linear interpolation at (n−1)q. Max/p95 intervals describe the observed sample, not unseen future tails. Escalation reasons can overlap; counts concern triggered pairs, and escalation failures preserve primary results.','','## Dev results','']

def table(headers,rows):
    return ['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |',*['| '+' | '.join(map(str,r))+' |' for r in rows]]
def ci(v,b,d=4): return f"{v:.{d}f} [{b['low']:.{d}f}, {b['high']:.{d}f}]"
def op_row(name,o):
    reasons='; '.join(f"{k}: {v['count']} [{v['ci']['low']:.0f}, {v['ci']['high']:.0f}]" for k,v in o['reasons'].items())
    return [name,f"{o['succeeded']}/{o['pairs']} [{o['success_95_ci']['low']:.3f}, {o['success_95_ci']['high']:.3f}]",*[ci(o[k],o[k+'_95_ci'],3) for k in ['p50','p95','max']],f"{o['within_40_s']}/20 [{o['within_40_s_95_ci']['low']:.0f}, {o['within_40_s_95_ci']['high']:.0f}]",f"{o['escalations']} [{o['escalations_95_ci']['low']:.0f}, {o['escalations_95_ci']['high']:.0f}]",reasons,str(len(o['escalation_errors']))]
def acc_row(name,r,s):
    m=r['scopes']['all']; b=m['bootstrap_95_ci']; a=s['absent_recall']
    return [name,ci(m['exact']['kappa']['value'],b['kappa']),ci(m['collapsed']['kappa']['value'],b['collapsed_kappa']),ci(m['evidence']['f1']['value'],b['evidence_f1']),ci(m['fit']['accuracy']['value'],b['fit_accuracy']),f"{a['correct']}/{a['support']} = "+ci(a['value'],a['ci'])]
names=['Reference — no escalation','A — Flash high','B — Argon medium']
lines+=table(['Run','Success [95% CI]','p50 s [CI]','p95 s [CI]','Max s [CI]','≤40 s [count CI]','Escalations [count CI]','Reasons [count CIs]','Escalation errors'],[op_row(n,supp[r['run']]['operational']) for n,r in zip(names,metrics['runs'])])+['']
lines+=table(['Run','Exact κ [95% CI]','Collapsed κ [CI]','Evidence F1 [CI]','Fit accuracy [CI]','Absent recall [CI]'],[acc_row(n,r,supp[r['run']]) for n,r in zip(names,metrics['runs'])])+['','## Mechanical selection','',selection['rule'],'']
for name,r in zip(names,selection['rows']):
    if name.startswith('Reference'):continue
    eligible=r['success']==20 and r['within_40_s']>=17
    lines.append(f"- {name}: {r['success']}/20 successful; {r['within_40_s']}/20 ≤40 s; {'eligible' if eligible else 'discarded'}. Collapsed κ={r['collapsed_kappa']:.8f}; evidence F1={r['evidence_f1']:.8f}; p95={r['p95']:.6f} s.")
chosen=selection['picked_before_reference_gate']
if chosen:
    ref=selection['rows'][0]
    lines+=['',f"Picked before reference gate: `{chosen['run']}`. Deltas versus reference: collapsed κ {chosen['collapsed_kappa']-ref['collapsed_kappa']:+.8f}; evidence F1 {chosen['evidence_f1']-ref['evidence_f1']:+.8f}. The reference gate uses strict improvement in at least one of these metrics (logical OR)."]
lines+=['',f"**Decision: {selection['decision']}.**",'']
if not selection['heldout_required']:
    lines+=['Step 2 was skipped as required. No new held-out run was made. Prior held-out results below are historical context, not inputs to dev selection.','','## Held-out comparison — skipped escalation','','Historical no-escalation values are transcribed from `data/eval/runs/20261122T122041Z-heldout-eval/RESULTS.md`, selected Flash low/v2/hedge20 row; they use 20 pairs and 140 criteria. The Flash high/v1 row there is a separate old baseline, not the requested no-escalation comparison.','']
    lines+=table(['Labels / run','Success','p50 / p95 / max s','≤40 s','Exact κ [95% CI]','Collapsed κ [CI]','Evidence F1 [CI]','Fit accuracy [CI]','Absent recall [CI]'],[['Primary / historical no escalation','20/20','8.190 / 33.637 / 41.069','19/20','0.587 [0.457, 0.710]','0.698 [0.559, 0.822]','0.848 [0.757, 0.924]','1.000 [1.000, 1.000]','20/21 = 0.952 [0.842, 1.000]'],['Strict / historical no escalation','20/20','8.190 / 33.637 / 41.069','19/20','0.657 [0.546, 0.763]','0.748 [0.641, 0.847]','0.862 [0.773, 0.932]','1.000 [1.000, 1.000]','28/33 = 0.848 [0.769, 0.947]'],['Primary / escalation','Skipped','—','—','—','—','—','—','—'],['Strict / escalation','Skipped','—','—','—','—','—','—','—']])+['']
else:
    lines+=['Held-out results must be appended before completion.','']
lines+=['## Per-pair dev latency and escalation flags','','Each row is one CV×JD pair. Reason lists refer to validated primary results; measured latency includes an escalation pass when triggered.','']
rows=[]
for name,r in zip(names,metrics['runs']):
    for p in supp[r['run']]['operational']['per_pair']:
        e=p['escalation']; rows.append([name,p['pair'],p['status'],f"{p['latency_s']:.6f}",'yes' if e.get('triggered') else 'no',', '.join(e.get('reasons',[])) or '—',f"{e['primary_latency_s']:.6f}" if e else '—',f"{e['escalation_latency_s']:.6f}" if e else '—','yes' if e.get('error') else 'no'])
lines+=table(['Run','Pair','Status','Latency s','Escalated','Reasons','Primary s','Escalation s','Escalation failed'],rows)+['','## Limitations','','- Small n: 10 CVs × 2 JDs per dataset; 20 dependent pairs and 140 criteria. Pair bootstrap preserves within-pair criteria but not the same CV’s cross-JD dependence; intervals are descriptive and do not establish significance. Success intervals assume independent pairs.','- Silver labels are LLM annotations, not human ground truth. Adjudicator/model-family overlap and dev-convention harmonisation can bias agreement; primary and strict held-out labels test different conventions.','- Shared gateway noise, retries, cancellation, model nondeterminism, and sequential order confound latency comparisons. Historical dev reference has no hedge; the new configurations use hedge20. Successful pair status can include escalation fallback, disclosed above.','- The escalation coverage band `[0.7, 0.9)` was fixed a priori for this task, not selected on these dev/held-out outputs; `needs_review` is the other fixed trigger.','- Escalation was added after the first held-out result at Dylan’s request. Even with dev-only selection and one conditional new held-out run, the held-out dataset has already been inspected and this is not a pristine first-use confirmatory test.','- Fit is a deterministic rubric proxy; weights and scores are uncalibrated, and expected_group is sampling metadata, not ground truth.','- Bootstrap intervals on observed extrema cannot guarantee future latency tails. Reported gateway response model aliases do not independently establish the requested selector’s reasoning policy.','','## Artifacts','','- `accuracy/metrics.json`, `accuracy/report.md`: unmodified dev evaluator outputs.','- `selection.json`: mechanical selection with full precision.','- `supplementary-metrics.json`: operational/absent-recall estimates and intervals, with per-pair escalation metadata.','- `input-provenance.json`, `read-only-verification.json`: input hashes and final read-only checks.','- `supplement.py`, `selection.py`, `report.py`: reproducible offline report helpers; these are new artifacts under runs, not changes to application code.']
(final/'RESULTS.md').write_text('\n'.join(lines)+'\n')
print(final/'RESULTS.md')
